// Decodable model for Fixtures/tools/tools.json, generated by
// tools/fixtures/tools/gen_tools.js from the reference JavaScript implementation.
//
// One `Scenario` is a deterministic event sequence for one state machine (or the
// StateMachineManager): crease-pattern setup, then ops (`transition`, `longTransition`,
// `batchPoint`, `batchLine`, `finish`, `selectAll`, `deselectAll`, `deleteSelected`, `getNew`,
// `toolType`, `newMachine`, `resetMachine`) each with the reference expectations recorded after
// the op: transition result, history-group summary, machine picked state and crease pattern.
import Foundation

struct ToolsFixture: Decodable {
    struct Constants: Decodable {
        struct ChangeLinePrefKeys: Decodable {
            let FROM: String
            let TO: String
        }

        let toolType: [String: Int]
        let transitionResult: [String: Int]
        let event: [String: Int]
        let changeLineRID: [String: Int]
        let deleteLineRID: [String: Int]
        let changeLinePrefKeys: ChangeLinePrefKeys
        let deleteLinePrefKey: String
    }

    struct Setup: Decodable {
        let defaultSquare: Bool
        /// `[x1, y1, x2, y2, lineType]`
        let lines: [[Double]]
    }

    struct InitialFlags: Decodable {
        let toolType: Int
        let directSelectionEnabled: Bool
        let hasBatchLineOperation: Bool
        let hasBatchPointOperation: Bool
    }

    struct ContextSpec: Decodable {
        let pref: [String: Int]?
        let angle: Double?
        let length: Double?
    }

    struct StateSnapshot: Decodable {
        /// `[x, y]` pairs, in Java `LinkedHashSet` insertion order.
        let pointsPicked: [[Double]]
        /// `[x1, y1, x2, y2, lineType]`, canonically sorted by the generator.
        let linesPicked: [[Double]]
        let tempPointPicked: [Double]?
        let tempLinePicked: [Double]?
    }

    struct CPSnapshot: Decodable {
        let lineCount: Int
        let pointCount: Int
        /// `[x1, y1, x2, y2, lineType]`, canonically sorted by the generator.
        let lines: [[Double]]
    }

    struct GroupSnapshot: Decodable {
        let isEmpty: Bool
        let historyItems: Int
    }

    struct ContextSnapshot: Decodable {
        let angle: Double
        let length: Double
    }

    struct Expect: Decodable {
        let result: Int?
        let group: GroupSnapshot?
        let state: StateSnapshot?
        let cp: CPSnapshot?
        let context: ContextSnapshot?
        let toolType: Int?
        let directSelectionEnabled: Bool?
        let hasBatchLineOperation: Bool?
        let hasBatchPointOperation: Bool?
    }

    struct Op: Decodable {
        let op: String
        let z: Bool?
        let point: [Double]?
        let radius: Double?
        let start: [Double]?
        let end: [Double]?
        let context: ContextSpec?
        let machine: String?
        let directSelection: Bool?
        let expect: Expect
    }

    struct Scenario: Decodable {
        let name: String
        let machine: String
        let manager: Bool
        let directSelection: Bool
        let setup: Setup
        let initial: InitialFlags?
        let ops: [Op]
        let final: CPSnapshot
    }

    let constants: Constants
    let scenarios: [Scenario]
}
